-- Начальные данные каталога. Сгенерировано scripts/generate-seed.ts —
-- править этот файл руками бессмысленно, он перезаписывается.

begin;

-- ── посты ──
insert into public.posts (slug, title, subtitle, category_id, cover, badges, blocks, read_min, published, sort_order) values (
  'remotion-video-kodom', 'Remotion: видео кодом', 'Ролик собирается из React, а не из дорожек в монтажке', 'ai',
  '{"from":"#F04A1E","to":"#2A0E0A","pattern":"grid","imageUrl":"https://kyutpzudsiifhdxysyff.supabase.co/storage/v1/object/public/covers/remotion-video-kodom.jpg"}'::jsonb, array['new', 'free'], '[{"type":"text","text":"Remotion делает видео из кода, а не из монтажа. Вы описываете ролик как обычную веб-страницу на React, а Remotion превращает её в готовый MP4. Никаких дорожек, ползунков и ручных ключевых точек."},{"type":"text","text":"Вспомните блокнот, где на каждой странице картинка чуть-чуть смещена: пролистали быстро — получился мультик. Здесь так же, только каждую страницу рисует код, а листает их тридцать раз в секунду. Кадр видео — это снимок страницы в конкретный момент времени."},{"type":"callout","tone":"info","text":"Remotion не заменяет камеру. Он заменяет ручную работу над той частью ролика, которую и так рисует компьютер: текст, интерфейсы, графику, титры, инфографику."},{"type":"heading","text":"Зачем это, если есть монтажка"},{"type":"text","text":"Как только видео становится кодом, с ним можно делать всё то же, что с кодом: копировать, переиспользовать, менять в одном месте и собирать по кнопке."},{"type":"list","items":["Поправили текст в одной строке — он поменялся во всём ролике.","Однажды написали печатающийся по буквам заголовок — используете его в каждом следующем видео.","Подставили данные из таблицы — цены, имена, статистику — и они попали в кадр без ручного перенабора.","Отдали задачу нейросети: для неё код — родной язык, а монтажная программа — нет."]},{"type":"text","text":"Компонент принимает пропсы — те же данные, что и любой React-компонент. Значит один ролик можно отрендерить сто раз с разными подписями: поздравления с именами, отчёты по клиентам, карточки товаров."},{"type":"code","lang":"tsx","code":"type Props = { name: string; city: string }\n\nexport const Greeting: React.FC<Props> = ({ name, city }) => (\n  <AbsoluteFill>\n    <h1>{name}, привет из {city}</h1>\n  </AbsoluteFill>\n)"},{"type":"command","command":"npx remotion render Greeting out/anna.mp4 --props=''{\"name\":\"Аня\",\"city\":\"Тбилиси\"}''","note":"Данные приходят аргументом — оборачивается в цикл по строкам таблицы."},{"type":"heading","text":"Из чего собран кадр"},{"type":"text","text":"У проекта два слоя. Композиция — паспорт ролика: размер, частота кадров, длина. Компоненты — то, что в этом ролике происходит."},{"type":"code","lang":"tsx","code":"import { Composition } from ''remotion''\nimport { Intro } from ''./Intro''\n\nexport const Root = () => (\n  <Composition\n    id=\"Intro\"\n    component={Intro}\n    durationInFrames={150}\n    fps={30}\n    width={1080}\n    height={1920}\n  />\n)"},{"type":"text","text":"Читается так: тридцать кадров в секунду, всего сто пятьдесят кадров — значит пять секунд. Кадр 1080 на 1920 — вертикаль под Reels, Shorts и Telegram."},{"type":"text","text":"Внутри компонента есть один хук, вокруг которого держится всё остальное: useCurrentFrame. Он отвечает на вопрос «какой сейчас кадр» — и от этого числа считается любое движение."},{"type":"code","lang":"tsx","code":"import { AbsoluteFill, useCurrentFrame, useVideoConfig } from ''remotion''\n\nexport const Intro = () => {\n  const frame = useCurrentFrame()\n  const { fps } = useVideoConfig()\n\n  // за первую секунду заголовок проявляется из нуля\n  const opacity = Math.min(frame / fps, 1)\n\n  return (\n    <AbsoluteFill style={{ justifyContent: ''center'', alignItems: ''center'' }}>\n      <h1 style={{ opacity }}>Цех</h1>\n    </AbsoluteFill>\n  )\n}"},{"type":"callout","tone":"warning","text":"CSS-анимации, setTimeout и любые «сами по себе идущие» эффекты в Remotion не работают. При рендере страница не проигрывается — у неё запрашивают отдельные кадры, иногда параллельно и не по порядку. Всё движение должно зависеть только от номера кадра."},{"type":"text","text":"Сцены собираются компонентом Sequence: он сдвигает время внутри себя. Обернули блок в Sequence с from={60} — и для этого блока отсчёт кадров начнётся на две секунды позже, а его собственный код об этом даже не узнает."},{"type":"heading","text":"Анимация — это формула"},{"type":"text","text":"В монтажке анимация — это две точки на таймлайне и кривая между ними, которую вы тянете мышкой. Здесь это функция: на входе номер кадра, на выходе число — прозрачность, сдвиг, масштаб."},{"type":"code","lang":"tsx","code":"import { interpolate, useCurrentFrame } from ''remotion''\n\nconst frame = useCurrentFrame()\n\n// с 15-го по 30-й кадр прозрачность идёт от 0 к 1\nconst opacity = interpolate(frame, [15, 30], [0, 1], {\n  extrapolateLeft: ''clamp'',\n  extrapolateRight: ''clamp'',\n})"},{"type":"text","text":"Clamp здесь обязателен. Без него формула честно продолжит считать за границами диапазона: до пятнадцатого кадра прозрачность уйдёт в минус, после тридцатого — за единицу, и элемент начнёт вести себя странно."},{"type":"text","text":"Линейное движение выглядит механическим — настоящие предметы разгоняются и тормозят. Функция spring имитирует пружину и делает это за вас."},{"type":"code","lang":"tsx","code":"import { spring, useCurrentFrame, useVideoConfig } from ''remotion''\n\nconst frame = useCurrentFrame()\nconst { fps } = useVideoConfig()\n\n// плавный выезд без отскока\nconst progress = spring({ frame, fps, config: { damping: 200 } })\nconst translateY = (1 - progress) * 80"},{"type":"list","items":["damping: 200 — спокойное появление без отскока, годится почти везде.","damping: 20, stiffness: 200 — резкое, «щелчком»: кнопки, счётчики, акценты.","damping: 8 — заметный отскок для игривых сцен. В деловом ролике будет лишним."]},{"type":"callout","tone":"success","text":"Написали такое появление один раз — вынесли в компонент Reveal и дальше просто оборачиваете в него всё, что должно выезжать. Ролики начинают выглядеть как одна серия, а не набор случайных эффектов."},{"type":"heading","text":"Звук задаёт длину ролика"},{"type":"text","text":"Озвучку не обязательно записывать голосом. Бесплатный edge-tts берёт текст и отдаёт готовый mp3 — этого достаточно для рекламного ролика или объяснялки."},{"type":"command","command":"pip install edge-tts","note":"Ставится один раз, работает без ключей и регистрации."},{"type":"command","command":"edge-tts --voice ru-RU-DmitryNeural --text \"Claude Code собирает видео, пока вы пишете текст\" --write-media public/voice.mp3","note":"Файл кладём в public — оттуда его забирает staticFile."},{"type":"code","lang":"tsx","code":"import { Audio } from ''@remotion/media''\nimport { staticFile } from ''remotion''\n\nexport const Scene = () => <Audio src={staticFile(''voice.mp3'')} />"},{"type":"text","text":"Главное правило со звуком: длина видео берётся из реальной длины аудио, а не ставится наугад. Секунды озвучки умножаются на частоту кадров."},{"type":"code","lang":"tsx","code":"import type { CalculateMetadataFunction } from ''remotion''\nimport { staticFile } from ''remotion''\nimport { getMediaMetadata } from ''./get-media-metadata''\n\nexport const calculateMetadata: CalculateMetadataFunction<Props> = async () => {\n  const { durationInSeconds } = await getMediaMetadata(staticFile(''voice.mp3''))\n\n  return { durationInFrames: Math.ceil(durationInSeconds * 30) }\n}"},{"type":"callout","tone":"warning","text":"Длина, вбитая руками, — источник половины проблем в готовых роликах: голос обрывается на полуслове или в конце висит секунда тишины. Пусть длину считает файл."},{"type":"heading","text":"Три скилла для Claude Code"},{"type":"text","text":"Скилл — это готовая инструкция, которая учит Claude Code делать конкретную часть работы. У Remotion таких инструкций три, и ставятся они одной командой."},{"type":"command","command":"npx skills add remotion-dev/skills","note":"После установки скиллы вызываются как команды: /remotion-create и другие."},{"type":"list","ordered":true,"items":["/remotion-create — создаёт проект и композицию: размер кадра, частота, заготовка сцены.","/remotion-markup — строит дизайн и анимации: как всё выглядит и как двигается.","/remotion-render — превращает проект в MP4 для Telegram, Reels или TikTok."]},{"type":"text","text":"Логика всегда одна: создать → нарисовать → отрендерить. Вы описываете ролик словами, а скиллы разводят задачу по трём этапам. Такого описания хватает для первого ролика:"},{"type":"prompt","title":"Ролик на 30 секунд","text":"Создай профессиональный Reel на 30 секунд про Remotion.\n\nФормат: вертикаль 1080×1920, 30 fps.\nСтиль: тёмный фон, монохромная палитра, крупная типографика.\n\nСцены:\n1. Терминал, в котором построчно печатается команда установки.\n2. Заголовок «Видео пишется кодом» — текст печатается по буквам.\n3. Три карточки с преимуществами, выезжают снизу по очереди с пружиной.\n4. Финал: логотип и призыв подписаться.\n\nДлину ролика посчитай из аудио, все анимации завяжи на useCurrentFrame, интерполяции обрежь clamp."},{"type":"callout","tone":"success","text":"Ролик, которым рекламируют эти скиллы, собран этими же скиллами. Ни монтажёра, ни таймлайна — только текст задачи, код и рендер."},{"type":"heading","text":"Первый ролик за вечер"},{"type":"text","text":"Порог входа ниже, чем кажется. Нужен компьютер с Node.js и один вечер, чтобы пройти путь целиком — от пустой папки до файла, который можно выложить."},{"type":"command","command":"npx create-video@latest","note":"Задаст пару вопросов и соберёт заготовку проекта."},{"type":"command","command":"npx remotion studio","note":"Предпросмотр в браузере: таймлайн, перемотка, мгновенное обновление после правки кода."},{"type":"command","command":"npx remotion render Intro out/video.mp4","note":"Первым аргументом — id композиции, вторым — куда положить файл."},{"type":"list","items":["Заходит: рекламные ролики, объяснялки, анимированная инфографика, титры, шаблонные видео с меняющимися данными.","Не заходит: съёмка живых людей, влоги, интервью и художественный монтаж «под настроение» — там сильнее обычная камера и рука монтажёра."]},{"type":"callout","tone":"info","text":"Проверьте себя перед рендером: длина считается по аудио, все анимации завязаны на useCurrentFrame, интерполяции обрезаны clamp, шрифты и картинки лежат в public. Четыре пункта закрывают почти все ошибки первых роликов."}]'::jsonb, 11, true, 0
) on conflict (slug) do update set
  title = excluded.title, subtitle = excluded.subtitle, category_id = excluded.category_id,
  cover = excluded.cover, badges = excluded.badges, blocks = excluded.blocks,
  read_min = excluded.read_min, sort_order = excluded.sort_order;

commit;
